}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-ai::before{
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/da835c40-d3c7-4462-ad4b-5c598284837b.png')!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .send-btn-custom{
  transform:translate(var(--real-send-x),var(--real-send-y))!important;
}
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-box-custom{
  min-height:40px!important;
  padding-top:10px!important;
  padding-bottom:10px!important;
}

/* AI 生成时底栏伪装 */
.stop-btn-custom{
  background:transparent!important;
  box-shadow:none!important;
  color:transparent!important;
  position:relative!important;
}
.stop-btn-custom svg{display:none!important;}
.chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::before{
  content:"";
  display:block;
  width:var(--right-btn-size)!important;
  height:var(--right-btn-size)!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/bfefc490-ba9e-4552-9926-abbb5b5d7cbe.png')!important;
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  position:absolute!important;
  top:var(--gen-icon-y)!important;
  left:var(--gen-plus-x)!important;
  transform:translateY(-50%)!important;
  pointer-events:none!important;
}
.chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::after{
  content:"";
  display:block;
  width:28px!important;
  height:28px!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/da835c40-d3c7-4462-ad4b-5c598284837b.png')!important;
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  position:absolute!important;
  top:var(--gen-sticker-y)!important;
  left:var(--gen-sticker-x)!important;
  transform:translateY(-50%)!important;
  pointer-events:none!important;
}
.chat-detail-screen:has(.stop-btn-custom) .input-action-bar-custom::after{
  content:"";
  display:block;
  width:17.9px!important;
  height:17.9px!important;
  background-image:url('https://nos.netease.com/vcloud-statistic/nrtc/59f469f5-0c70-43ce-ae1e-4c633e9a4e9a.png')!important;
  background-size:contain;
  background-repeat:no-repeat;
  background-position:center;
  position:absolute!important;
  top:var(--gen-mic-y)!important;
  right:calc(var(--gen-mic-x) * -1)!important;
  transform:translateY(-50%)!important;
  pointer-events:none!important;
  z-index:10!important;
}

/* 禁用左侧菜单键旋转 */
.input-btn-plus,
.input-btn-plus:active,
.input-btn-plus:focus,
.input-btn-plus[class*="open"],
.input-btn-plus[class*="active"],
.input-action-bar-custom:has(.more-options-popup) .input-btn-plus{
  transform:none!important;
  rotate:0deg!important;
  transition:none!important;
}

/* 夜间底栏防白线 */
@media (prefers-color-scheme: dark) {
  body .input-area-custom,
  body .input-area-custom > *,
  body .input-action-bar-custom{
    background-color:#1E1E1E!important;
    background-image:linear-gradient(#1E1E1E,#1E1E1E)!important;
    background-size:100% 100%!important;
    background-repeat:no-repeat!important;
    backdrop-filter:none!important;
    -webkit-backdrop-filter:none!important;
    box-shadow:none!important;
    border-top:none!important;
    border-top-color:transparent!important;
  }

  /* 夜间图标防刺眼 */
  body .input-btn-plus::before{
    filter:invert(1) opacity(var(--dark-icon-opacity))!important;
  }
  body .input-btn-mic::before,
  body .input-btn-sticker::before,
  body .input-btn-ai::before,
  body .send-btn-custom::before{
    filter:invert(1) opacity(var(--dark-icon-opacity))!important;
  }
  body .chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::before,
  body .chat-detail-screen:has(.stop-btn-custom) .stop-btn-custom::after,
  body .chat-detail-screen:has(.stop-btn-custom) .input-action-bar-custom::after{
    filter:invert(1) opacity(var(--dark-icon-opacity))!important;
  }
}

/* =================================== */
/* 气泡微信化 */
/* =================================== */
:root{
  --bubble-me-padding:8px 11px;
  --bubble-them-padding:8px 11px;
  --wechat-bubble-radius:4px;
  --bubble-tail-width:15.5px;
  --bubble-tail-height:15.5px;
  --bubble-tail-top:11px;
  --bubble-me-tail-right:-3px;
  --bubble-them-tail-left:-3px;
}
.bubble-me-custom,
.bubble-them-custom{
  border-radius:var(--wechat-bubble-radius)!important;
  position:relative!important;
  overflow:visible!important;
  box-shadow:none!important;
  border:none!important;
}
/* 我方气泡小角：纯 CSS 圆角菱形 */
.bubble-me-custom::before{
  content:"" !important;
  display:block !important;
  position:absolute !important;
  top:var(--bubble-tail-top)!important;
  right:var(--bubble-me-tail-right)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-me-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important; 
}
/* 对方气泡小角：纯 CSS 圆角菱形 */
.bubble-them-custom::before{
  content:"" !important;
  display:block !important;
  position:absolute !important;
  top:var(--bubble-tail-top)!important;
  left:var(--bubble-them-tail-left)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-them-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
}
.bubble-me-custom,
.bubble-them-custom {
    max-width: 72vw !important; 
    box-sizing: border-box !important;
    word-wrap: break-word !important;
    word-break: break-word !important; /* 👈 恢复成这个，保护英文单词完整 */
    /* 👇 保护你心心念念的中文“左右对称” */
    text-align: justify !important;
    text-justify: inter-ideograph !important;
}

/* =================================== */
/* 引用条 */
/* =================================== */
:root{
  --reply-bar-bg:var(--reply-detached-bg);
  --reply-bar-border:var(--reply-detached-border);
  --reply-bar-radius:var(--reply-detached-radius);
  --reply-bar-padding:1px 4px;
  --reply-bar-margin-bottom:5px;
  --reply-bar-shadow:none;
  --reply-bar-backdrop:none;
  --reply-bar-content-direction:row;
  --reply-bar-content-gap:2px;
  --reply-bar-content-padding-left:0;
  --reply-bar-accent-border:none;
  --reply-bar-name-color:var(--reply-detached-name-color);
  --reply-bar-name-size:13px;
  --reply-bar-name-weight:normal;
  --reply-bar-text-color:var(--reply-detached-text-color);
  --reply-bar-text-size:13px;

  --reply-detached-radius:4px;
  --reply-detached-padding:5px 8px;
  --reply-detached-margin-top:4px;
  --reply-detached-name-size:11.5px;
  --reply-detached-text-size:11.5px;
